-- Construction Material Price Monitor
-- Server-managed dataset. Public/client roles are intentionally denied direct table access.
create table if not exists public.sources (id bigint generated by default as identity primary key,code text unique not null,name text not null,base_url text,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.products (id bigint generated by default as identity primary key,canonical_name text not null,brand text,category text,subcategory text,unit text,specification jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.listings (id bigint generated by default as identity primary key,source_id bigint not null references public.sources(id) on delete cascade,product_id bigint references public.products(id) on delete set null,source_sku text,source_name text not null,product_url text not null,image_url text,current_price numeric(12,2),regular_price numeric(12,2),promo_price numeric(12,2),currency text not null default 'THB',stock_status text,source_category text,raw_details jsonb not null default '{}'::jsonb,first_seen_at timestamptz not null default now(),last_checked_at timestamptz,unique(source_id,product_url));
create table if not exists public.price_history (id bigint generated by default as identity primary key,listing_id bigint not null references public.listings(id) on delete cascade,price numeric(12,2),regular_price numeric(12,2),promo_price numeric(12,2),stock_status text,checked_at timestamptz not null default now());
create index if not exists idx_price_history_listing_checked on public.price_history(listing_id,checked_at desc);
create table if not exists public.crawl_logs (id bigint generated by default as identity primary key,source_id bigint references public.sources(id) on delete set null,started_at timestamptz not null default now(),finished_at timestamptz,status text not null,items_found integer not null default 0,items_updated integer not null default 0,error_message text);
alter table public.sources enable row level security;alter table public.products enable row level security;alter table public.listings enable row level security;alter table public.price_history enable row level security;alter table public.crawl_logs enable row level security;
revoke all on public.sources,public.products,public.listings,public.price_history,public.crawl_logs from anon,authenticated;
insert into public.sources(code,name,base_url) values ('dohome','DoHome','https://www.dohome.co.th/'),('homepro','HomePro','https://www.homepro.co.th/'),('thaiwatsadu','Thai Watsadu','https://www.thaiwatsadu.com/'),('globalhouse','Global House','https://globalhouse.co.th/') on conflict(code) do update set name=excluded.name,base_url=excluded.base_url;